using System;using BeamScheduleFormatter;class BeamQuantitiesTests{static void Main(){var e=BeamQuantities.Calculate(300,600,5,2,false,150);var g=BeamQuantities.Calculate(300,600,5,2,true,0);if(Math.Abs(e.Concrete-1.8)>1e-9||Math.Abs(e.Formwork-12)>1e-9||Math.Abs(g.Formwork-12)>1e-9||g.BottomForms!=0)throw new Exception("Beam volume/formwork mismatch");var full=BeamQuantities.Calculate(300,600,5,2,false,0);if(Math.Abs(full.Formwork-15)>1e-9)throw new Exception("Soffit missing");bool bad=false;try{BeamQuantities.Calculate(300,600,5,2,false,600);}catch{bad=true;}if(!bad)throw new Exception("Invalid slab depth accepted");Console.WriteLine("PASS: beam concrete, gravel/elevated formwork, quantity, slab-side deductions and invalid depth checks.");}}
